@Test
public void testMultipartPartStringPartsMultiCharsets() throws Exception {
    final String s1 = constructString(SWISS_GERMAN_HELLO);
    final String s2 = constructString(RUSSIAN_HELLO);
    final MultipartPart p1 = MultipartPartBuilder.create(new StringBody(s1, ContentType.create("text/plain", Charset.forName("ISO-8859-1")))).build();
    final MultipartPart p2 = MultipartPartBuilder.create(new StringBody(s2, ContentType.create("text/plain", Charset.forName("KOI8-R")))).build();
    final HttpStrictMultipart multipart = new HttpStrictMultipart(null, "foo", Arrays.<MultipartPart>asList(p1, p2));
    final ByteArrayOutputStream out1 = new ByteArrayOutputStream();
    multipart.writeTo(out1);
    out1.close();
    final ByteArrayOutputStream out2 = new ByteArrayOutputStream();
    out2.write(("--foo\r\n" + "Content-Type: text/plain; charset=ISO-8859-1\r\n" + "\r\n").getBytes(StandardCharsets.US_ASCII));
    out2.write(s1.getBytes(StandardCharsets.ISO_8859_1));
    out2.write(("\r\n" + "--foo\r\n" + "Content-Type: text/plain; charset=KOI8-R\r\n" + "\r\n").getBytes(StandardCharsets.US_ASCII));
    out2.write(s2.getBytes(Charset.forName("KOI8-R")));
    out2.write(("\r\n" + "--foo--\r\n").getBytes(StandardCharsets.US_ASCII));
    out2.close();
    final byte[] actual = out1.toByteArray();
    final byte[] expected = out2.toByteArray();
    Assert.assertEquals(expected.length, actual.length);
    for (int i = 0; i < actual.length; i++) {
        Assert.assertEquals(expected[i], actual[i]);
    }
    Assert.assertEquals(expected.length, multipart.getTotalLength());
}

