    final HttpRouteDirector rowdy = new BasicRouteDirector();
    final HttpRoute route1cA = new HttpRoute(TARGET1, null, chainA, false, TunnelType.PLAIN, LayerType.PLAIN);
    final HttpRoute route1cB = new HttpRoute(TARGET1, null, chainB, false, TunnelType.PLAIN, LayerType.PLAIN);
    final HttpRoute route1cC = new HttpRoute(TARGET1, null, chainC, false, TunnelType.PLAIN, LayerType.PLAIN);
    final HttpRoute route1cD = new HttpRoute(TARGET1, null, chainC, false, TunnelType.PLAIN, LayerType.PLAIN);
    int step = rowdy.nextStep(route1cA, null);
    Assert.assertEquals("wrong step to route1cA", HttpRouteDirector.CONNECT_PROXY, step);
    step = rowdy.nextStep(route1cB, null);
    Assert.assertEquals("wrong step to route1cB", HttpRouteDirector.CONNECT_PROXY, step);
    step = rowdy.nextStep(route1cC, null);
    Assert.assertEquals("wrong step to route1cC", HttpRouteDirector.CONNECT_PROXY, step);
    step = rowdy.nextStep(route1cD, null);
    Assert.assertEquals("wrong step to route1cD", HttpRouteDirector.CONNECT_PROXY, step);
    step = rowdy.nextStep(route1cB, route1cA);
    Assert.assertEquals("wrong step to route 1cB from 1cA", HttpRouteDirector.TUNNEL_PROXY, step);
    step = rowdy.nextStep(route1cB, route1cB);
    Assert.assertEquals("complete route 1cB not detected", HttpRouteDirector.COMPLETE, step);
    step = rowdy.nextStep(route1cB, route1cC);
    Assert.assertEquals("unreachable route 1cB from 1cC not detected", HttpRouteDirector.UNREACHABLE, step);
    step = rowdy.nextStep(route1cB, route1cD);
    Assert.assertEquals("unreachable route 1cB from 1cD not detected", HttpRouteDirector.UNREACHABLE, step);
    step = rowdy.nextStep(route1cA, route1cB);
    Assert.assertEquals("unreachable route 1cA from 1cB not detected", HttpRouteDirector.UNREACHABLE, step);
}

