    step = rowdy.nextStep(route1s, null);
    Assert.assertEquals("wrong step to route1s", HttpRouteDirector.CONNECT_TARGET, step);
    // unrequested security is currently not tolerated
    step = rowdy.nextStep(route1u, route1s);
    Assert.assertEquals("unreachable route 1u from 1s not detected", HttpRouteDirector.UNREACHABLE, step);
    // secure layering of direct connections is currently not supported
    step = rowdy.nextStep(route1s, route1u);
    Assert.assertEquals("unreachable route 1s from 1u not detected", HttpRouteDirector.UNREACHABLE, step);
    step = rowdy.nextStep(route1s, route1p1u);
    Assert.assertEquals("unreachable route 1s from 1p1u not detected", HttpRouteDirector.UNREACHABLE, step);
    step = rowdy.nextStep(route1s, route1p1s);
    Assert.assertEquals("unreachable route 1s from 1p1s not detected", HttpRouteDirector.UNREACHABLE, step);
}

@Test
public void testProxyTLS() {
    final HttpRouteDirector rowdy = new BasicRouteDirector();
    final HttpRoute route1 = new HttpRoute(TARGET1, null, PROXY1, false, TunnelType.PLAIN, LayerType.PLAIN);
    final HttpRoute route1t = new HttpRoute(TARGET1, null, PROXY1, false, TunnelType.TUNNELLED, LayerType.PLAIN);
    final HttpRoute route1tl = new HttpRoute(TARGET1, null, PROXY1, false, TunnelType.TUNNELLED, LayerType.LAYERED);
    final HttpRoute route1s = new HttpRoute(TARGET1, null, PROXY1, true, TunnelType.PLAIN, LayerType.PLAIN);
    final HttpRoute route1ts = new HttpRoute(TARGET1, null, PROXY1, true, TunnelType.TUNNELLED, LayerType.PLAIN);
    final HttpRoute route1tls = new HttpRoute(TARGET1, null, PROXY1, true, TunnelType.TUNNELLED, LayerType.LAYERED);
    // we don't consider a route that is layered but not tunnelled
    int step = rowdy.nextStep(route1, null);
    Assert.assertEquals("wrong step to route1", HttpRouteDirector.CONNECT_PROXY, step);
    step = rowdy.nextStep(route1t, null);
    Assert.assertEquals("wrong step to route1t", HttpRouteDirector.CONNECT_PROXY, step);
    step = rowdy.nextStep(route1tl, null);
    Assert.assertEquals("wrong step to route1tl", HttpRouteDirector.CONNECT_PROXY, step);
    step = rowdy.nextStep(route1s, null);
    Assert.assertEquals("wrong step to route1s", HttpRouteDirector.CONNECT_PROXY, step);
    step = rowdy.nextStep(route1ts, null);
    Assert.assertEquals("wrong step to route1ts", HttpRouteDirector.CONNECT_PROXY, step);
    step = rowdy.nextStep(route1tls, null);
    Assert.assertEquals("wrong step to route1tls", HttpRouteDirector.CONNECT_PROXY, step);
    step = rowdy.nextStep(route1, route1);
    Assert.assertEquals("complete route1 not detected", HttpRouteDirector.COMPLETE, step);
    step = rowdy.nextStep(route1t, route1t);
    Assert.assertEquals("complete route1t not detected", HttpRouteDirector.COMPLETE, step);
    step = rowdy.nextStep(route1tl, route1tl);
    Assert.assertEquals("complete route1tl not detected", HttpRouteDirector.COMPLETE, step);
    step = rowdy.nextStep(route1s, route1s);
    Assert.assertEquals("complete route1s not detected", HttpRouteDirector.COMPLETE, step);
    step = rowdy.nextStep(route1ts, route1ts);
    Assert.assertEquals("complete route1ts not detected", HttpRouteDirector.COMPLETE, step);
    step = rowdy.nextStep(route1tls, route1tls);
    Assert.assertEquals("complete route1tls not detected", HttpRouteDirector.COMPLETE, step);
    step = rowdy.nextStep(route1, route1t);
    Assert.assertEquals("unreachable route1 from 1t not detected", HttpRouteDirector.UNREACHABLE, step);
    step = rowdy.nextStep(route1, route1tl);
    Assert.assertEquals("unreachable route1 from 1tl not detected", HttpRouteDirector.UNREACHABLE, step);
    // unrequested security is currently not tolerated
    step = rowdy.nextStep(route1, route1s);
    Assert.assertEquals("unreachable route1 from 1s not detected", HttpRouteDirector.UNREACHABLE, step);
    step = rowdy.nextStep(route1, route1ts);
    Assert.assertEquals("unreachable route1 from 1ts not detected", HttpRouteDirector.UNREACHABLE, step);
    step = rowdy.nextStep(route1, route1tls);
    Assert.assertEquals("unreachable route1 from 1tls not detected", HttpRouteDirector.UNREACHABLE, step);
    // securing requires layering
    step = rowdy.nextStep(route1s, route1);
    Assert.assertEquals("unreachable route1s from 1 not detected", HttpRouteDirector.UNREACHABLE, step);
    // securing requires layering, and multiple layers are not supported
    step = rowdy.nextStep(route1tls, route1tl);
    Assert.assertEquals("unreachable route1tls from 1tl not detected", HttpRouteDirector.UNREACHABLE, step);
    // cases where tunnelling to the target is required
    step = rowdy.nextStep(route1t, route1);
    Assert.assertEquals("wrong step to route1t from 1", HttpRouteDirector.TUNNEL_TARGET, step);
    step = rowdy.nextStep(route1tl, route1);
    Assert.assertEquals("wrong step to route1tl from 1", HttpRouteDirector.TUNNEL_TARGET, step);
    step = rowdy.nextStep(route1tls, route1);
    Assert.assertEquals("wrong step to route1tls from 1", HttpRouteDirector.TUNNEL_TARGET, step);
    // cases where layering on the tunnel is required
    step = rowdy.nextStep(route1tl, route1t);
    Assert.assertEquals("wrong step to route1tl from 1t", HttpRouteDirector.LAYER_PROTOCOL, step);
    step = rowdy.nextStep(route1tl, route1ts);
    Assert.assertEquals("wrong step to route1tl from 1ts", HttpRouteDirector.LAYER_PROTOCOL, step);
    step = rowdy.nextStep(route1tls, route1t);
    Assert.assertEquals("wrong step to route1tls from 1t", HttpRouteDirector.LAYER_PROTOCOL, step);
    step = rowdy.nextStep(route1tls, route1ts);
    Assert.assertEquals("wrong step to route1tls from 1ts", HttpRouteDirector.LAYER_PROTOCOL, step);
    // There are some odd cases left over, like having a secure tunnel
    // that becomes unsecure by layering, or a secure connection to a
    // proxy that becomes unsecure by tunnelling to another proxy.
}

