@Test
public void testCstrFullRoute() {
    // create a route with all arguments and check the details
    final HttpHost[] chain3 = { PROXY1, PROXY2, PROXY3 };
    final HttpRoute route = new HttpRoute(TARGET1, LOCAL41, chain3, false, TunnelType.PLAIN, LayerType.PLAIN);
    Assert.assertEquals("wrong target", TARGET1, route.getTargetHost());
    Assert.assertEquals("wrong local address", LOCAL41, route.getLocalAddress());
    Assert.assertEquals("wrong proxy host", PROXY1, route.getProxyHost());
    Assert.assertEquals("wrong hop count", 4, route.getHopCount());
    Assert.assertEquals("wrong hop 0", PROXY1, route.getHopTarget(0));
    Assert.assertEquals("wrong hop 1", PROXY2, route.getHopTarget(1));
    Assert.assertEquals("wrong hop 2", PROXY3, route.getHopTarget(2));
    Assert.assertEquals("wrong hop 3", TARGET1, route.getHopTarget(3));
    Assert.assertFalse("wrong flag: secured", route.isSecure());
    Assert.assertFalse("wrong flag: tunnelled", route.isTunnelled());
    Assert.assertFalse("wrong flag: layered", route.isLayered());
    final String routestr = route.toString();
    Assert.assertTrue("missing target in toString", routestr.contains(TARGET1.getHostName()));
    Assert.assertTrue("missing local address in toString", routestr.contains(LOCAL41.toString()));
    Assert.assertTrue("missing proxy 1 in toString", routestr.contains(PROXY1.getHostName()));
    Assert.assertTrue("missing proxy 2 in toString", routestr.contains(PROXY2.getHostName()));
    Assert.assertTrue("missing proxy 3 in toString", routestr.contains(PROXY3.getHostName()));
}

@Test
public void testCstrFullFlags() {
    // tests the flag parameters in the full-blown constructor
    final HttpHost[] chain3 = { PROXY1, PROXY2, PROXY3 };
    final HttpRoute routefff = new HttpRoute(TARGET1, LOCAL41, chain3, false, TunnelType.PLAIN, LayerType.PLAIN);
    final HttpRoute routefft = new HttpRoute(TARGET1, LOCAL41, chain3, false, TunnelType.PLAIN, LayerType.LAYERED);
    final HttpRoute routeftf = new HttpRoute(TARGET1, LOCAL41, chain3, false, TunnelType.TUNNELLED, LayerType.PLAIN);
    final HttpRoute routeftt = new HttpRoute(TARGET1, LOCAL41, chain3, false, TunnelType.TUNNELLED, LayerType.LAYERED);
    final HttpRoute routetff = new HttpRoute(TARGET1, LOCAL41, chain3, true, TunnelType.PLAIN, LayerType.PLAIN);
    final HttpRoute routetft = new HttpRoute(TARGET1, LOCAL41, chain3, true, TunnelType.PLAIN, LayerType.LAYERED);
    final HttpRoute routettf = new HttpRoute(TARGET1, LOCAL41, chain3, true, TunnelType.TUNNELLED, LayerType.PLAIN);
    final HttpRoute routettt = new HttpRoute(TARGET1, LOCAL41, chain3, true, TunnelType.TUNNELLED, LayerType.LAYERED);
    Assert.assertFalse("routefff.secure", routefff.isSecure());
    Assert.assertFalse("routefff.tunnel", routefff.isTunnelled());
    Assert.assertFalse("routefff.layer", routefff.isLayered());
    Assert.assertFalse("routefft.secure", routefft.isSecure());
    Assert.assertFalse("routefft.tunnel", routefft.isTunnelled());
    Assert.assertTrue("routefft.layer", routefft.isLayered());
    Assert.assertFalse("routeftf.secure", routeftf.isSecure());
    Assert.assertTrue("routeftf.tunnel", routeftf.isTunnelled());
    Assert.assertFalse("routeftf.layer", routeftf.isLayered());
    Assert.assertFalse("routeftt.secure", routeftt.isSecure());
    Assert.assertTrue("routeftt.tunnel", routeftt.isTunnelled());
    Assert.assertTrue("routeftt.layer", routeftt.isLayered());
    Assert.assertTrue("routetff.secure", routetff.isSecure());
    Assert.assertFalse("routetff.tunnel", routetff.isTunnelled());
    Assert.assertFalse("routetff.layer", routetff.isLayered());
    Assert.assertTrue("routetft.secure", routetft.isSecure());
    Assert.assertFalse("routetft.tunnel", routetft.isTunnelled());
    Assert.assertTrue("routetft.layer", routetft.isLayered());
    Assert.assertTrue("routettf.secure", routettf.isSecure());
    Assert.assertTrue("routettf.tunnel", routettf.isTunnelled());
    Assert.assertFalse("routettf.layer", routettf.isLayered());
    Assert.assertTrue("routettt.secure", routettt.isSecure());
    Assert.assertTrue("routettt.tunnel", routettt.isTunnelled());
    Assert.assertTrue("routettt.layer", routettt.isLayered());
    final Set<HttpRoute> routes = new HashSet<>();
    routes.add(routefff);
    routes.add(routefft);
    routes.add(routeftf);
    routes.add(routeftt);
    routes.add(routetff);
    routes.add(routetft);
    routes.add(routettf);
    routes.add(routettt);
    Assert.assertEquals("some flagged routes are equal", 8, routes.size());
    // we can't test hashCode in general due to its dependency
    // on InetAddress and HttpHost, but we can check for the flags
    final Set<Integer> routecodes = new HashSet<>();
    routecodes.add(Integer.valueOf(routefff.hashCode()));
    routecodes.add(Integer.valueOf(routefft.hashCode()));
