@Test
public void testRewrite() throws Exception {
    final HttpHost target = new HttpHost("thathost", -1);
    Assert.assertEquals("http://thathost/stuff", URIUtils.rewriteURI(URI.create("http://thishost/stuff"), target).toString());
    Assert.assertEquals("/stuff", URIUtils.rewriteURI(URI.create("http://thishost/stuff"), null).toString());
    Assert.assertEquals("/", URIUtils.rewriteURI(URI.create("http://thishost//"), null).toString());
    Assert.assertEquals("/stuff/morestuff", URIUtils.rewriteURI(URI.create("http://thishost//stuff/morestuff"), null).toString());
