    Assert.assertEquals("http://thathost/#crap", URIUtils.rewriteURI(URI.create("http://thishost#crap"), target, false).toString());
    Assert.assertEquals("/stuff/", URIUtils.rewriteURI(URI.create("http://thishost//////////////stuff/"), null).toString());
    Assert.assertEquals("http://thathost/stuff", URIUtils.rewriteURI(URI.create("http://thathost/stuff")).toString());
    Assert.assertEquals("http://thathost/stuff", URIUtils.rewriteURI(URI.create("http://thathost/stuff#fragment")).toString());
    Assert.assertEquals("http://thathost/stuff", URIUtils.rewriteURI(URI.create("http://userinfo@thathost/stuff#fragment")).toString());
    Assert.assertEquals("http://thathost/", URIUtils.rewriteURI(URI.create("http://thathost")).toString());
    Assert.assertEquals("http://thathost/", URIUtils.rewriteURI(URI.create("http://ThatHost")).toString());
    Assert.assertEquals("http://That_Host/", URIUtils.rewriteURI(URI.create("http://That_Host")).toString());
    Assert.assertEquals("http://thishost/Fragment_identifier%23Examples", URIUtils.rewriteURI(URI.create("http://thishost/Fragment_identifier%23Examples")).toString());
