    final ClassicHttpResponse resp1 = HttpTestUtils.make304Response();
    resp1.setHeader("Date", DateUtils.formatDate(now));
    resp1.setHeader("Cache-control", "max-age=600");
    resp1.setHeader("Expires", DateUtils.formatDate(inTenMinutes));
    expect(mockExecChain.proceed(isA(ClassicHttpRequest.class), isA(ExecChain.Scope.class))).andReturn(resp1).once();
    expect(mockExecChain.proceed(isA(ClassicHttpRequest.class), isA(ExecChain.Scope.class))).andThrow(new AssertionFailedError("Should have reused cached 304 response")).anyTimes();
    replayMocks();
    execute(req1);
    final ClassicHttpResponse result = execute(req2);
    verifyMocks();
    Assert.assertEquals(HttpStatus.SC_NOT_MODIFIED, result.getCode());
    Assert.assertFalse(result.containsHeader("Last-Modified"));
}

