@Test
public void testBasicSSL() throws Exception {
    // @formatter:off
    this.server = ServerBootstrap.bootstrap().setSslContext(SSLTestContexts.createServerSSLContext()).create();
    // @formatter:on
    this.server.start();
    final HttpContext context = new BasicHttpContext();
    final TestX509HostnameVerifier hostVerifier = new TestX509HostnameVerifier();
    final SSLConnectionSocketFactory socketFactory = new SSLConnectionSocketFactory(SSLTestContexts.createClientSSLContext(), hostVerifier);
    try (final Socket socket = socketFactory.createSocket(context)) {
        final InetSocketAddress remoteAddress = new InetSocketAddress("localhost", this.server.getLocalPort());
        final HttpHost target = new HttpHost("https", "localhost", this.server.getLocalPort());
        try (final SSLSocket sslSocket = (SSLSocket) socketFactory.connectSocket(TimeValue.ZERO_MILLISECONDS, socket, target, remoteAddress, null, context)) {
            final SSLSession sslsession = sslSocket.getSession();
            Assert.assertNotNull(sslsession);
            Assert.assertTrue(hostVerifier.isFired());
        }
    }
}

