@Test
public void testStatefulConnections() throws Exception {
    final int workerCount = 5;
    final int requestCount = 5;
    this.server.registerHandler("*", new SimpleService());
    this.connManager.setMaxTotal(workerCount);
    this.connManager.setDefaultMaxPerRoute(workerCount);
    final UserTokenHandler userTokenHandler = new UserTokenHandler() {

        @Override
        public Object getUserToken(final HttpRoute route, final HttpContext context) {
            final String id = (String) context.getAttribute("user");
            return id;
        }
    };
    this.clientBuilder.setUserTokenHandler(userTokenHandler);
    final HttpHost target = start();
    final HttpClientContext[] contexts = new HttpClientContext[workerCount];
    final HttpWorker[] workers = new HttpWorker[workerCount];
    for (int i = 0; i < contexts.length; i++) {
        final HttpClientContext context = HttpClientContext.create();
        contexts[i] = context;
        workers[i] = new HttpWorker("user" + i, context, requestCount, target, this.httpclient);
    }
    for (final HttpWorker worker : workers) {
        worker.start();
    }
    for (final HttpWorker worker : workers) {
        worker.join(LONG_TIMEOUT.toMilliseconds());
    }
    for (final HttpWorker worker : workers) {
        final Exception ex = worker.getException();
        if (ex != null) {
            throw ex;
        }
        Assert.assertEquals(requestCount, worker.getCount());
    }
    for (final HttpContext context : contexts) {
        final String state0 = (String) context.getAttribute("r0");
        Assert.assertNotNull(state0);
        for (int r = 1; r < requestCount; r++) {
            Assert.assertEquals(state0, context.getAttribute("r" + r));
        }
    }
}

@Test
public void testRouteSpecificPoolRecylcing() throws Exception {
    // This tests what happens when a maxed connection pool needs
    // to kill the last idle connection to a route to build a new
    // one to the same route.
    final int maxConn = 2;
    this.server.registerHandler("*", new SimpleService());
    this.connManager.setMaxTotal(maxConn);
    this.connManager.setDefaultMaxPerRoute(maxConn);
    final UserTokenHandler userTokenHandler = new UserTokenHandler() {

        @Override
        public Object getUserToken(final HttpRoute route, final HttpContext context) {
            return context.getAttribute("user");
        }
    };
    this.clientBuilder.setUserTokenHandler(userTokenHandler);
    final HttpHost target = start();
    // Bottom of the pool : a *keep alive* connection to Route 1.
    final HttpContext context1 = new BasicHttpContext();
    context1.setAttribute("user", "stuff");
    final ClassicHttpResponse response1 = this.httpclient.execute(target, new HttpGet("/"), context1);
    EntityUtils.consume(response1.getEntity());
    // The ConnPoolByRoute now has 1 free connection, out of 2 max
    // The ConnPoolByRoute has one RouteSpcfcPool, that has one free connection
    // for [localhost][stuff]
    Thread.sleep(100);
    // Send a very simple HTTP get (it MUST be simple, no auth, no proxy, no 302, no 401, ...)
    // Send it to another route. Must be a keepalive.
    final HttpContext context2 = new BasicHttpContext();
    final ClassicHttpResponse response2 = this.httpclient.execute(new HttpHost("127.0.0.1", this.server.getPort()), new HttpGet("/"), context2);
    EntityUtils.consume(response2.getEntity());
    // ConnPoolByRoute now has 2 free connexions, out of its 2 max.
    // The [localhost][stuff] RouteSpcfcPool is the same as earlier
    // And there is a [127.0.0.1][null] pool with 1 free connection
    Thread.sleep(100);
    // This will put the ConnPoolByRoute to the targeted state :
    // [localhost][stuff] will not get reused because this call is [localhost][null]
    // So the ConnPoolByRoute will need to kill one connection (it is maxed out globally).
    // The killed conn is the oldest, which means the first HTTPGet ([localhost][stuff]).
    // When this happens, the RouteSpecificPool becomes empty.
    final HttpContext context3 = new BasicHttpContext();
    final ClassicHttpResponse response3 = this.httpclient.execute(target, new HttpGet("/"), context3);
    // If the ConnPoolByRoute did not behave coherently with the RouteSpecificPool
    // this may fail. Ex : if the ConnPool discared the route pool because it was empty,
    // but still used it to build the request3 connection.
    EntityUtils.consume(response3.getEntity());
}

// this timeout (in ms) needs to be extended if you're actively debugging the code
@Test(timeout = 30000)
public void testNoInfiniteLoopOnSPNOutsideDomain() throws Exception {
    this.server.registerHandler("/", new HttpRequestHandler() {

        @Override
        public void handle(final ClassicHttpRequest request, final ClassicHttpResponse response, final HttpContext context) throws HttpException, IOException {
            response.addHeader(HttpHeaders.WWW_AUTHENTICATE, StandardAuthScheme.SPNEGO);
            response.setCode(HttpStatus.SC_UNAUTHORIZED);
        }
    });
    Assume.assumeTrue("Test can only be run on Windows", WinHttpClients.isWinAuthAvailable());
    // HTTPCLIENT-1545
    // If a service principal name (SPN) from outside your Windows domain tree (e.g., HTTP/example.com) is used,
    // InitializeSecurityContext will return SEC_E_DOWNGRADE_DETECTED (decimal: -2146892976, hex: 0x80090350).
    // Because WindowsNegotiateScheme wasn't setting the completed state correctly when authentication fails,
    // HttpClient goes into an infinite loop, constantly retrying the negotiate authentication to kingdom
    // come. This error message, "The system detected a possible attempt to compromise security. Please ensure that
    // you can contact the server that authenticated you." is associated with SEC_E_DOWNGRADE_DETECTED.
    final Registry<AuthSchemeFactory> authSchemeRegistry = RegistryBuilder.<AuthSchemeFactory>create().register(StandardAuthScheme.SPNEGO, new AuthSchemeFactory() {

        @Override
        public AuthScheme create(final HttpContext context) {
            return new WindowsNegotiateSchemeGetTokenFail(StandardAuthScheme.SPNEGO, "HTTP/example.com");
        }
    }).build();
    final CloseableHttpClient customClient = HttpClientBuilder.create().setDefaultAuthSchemeRegistry(authSchemeRegistry).build();
    final HttpHost target = start();
    final HttpGet httpGet = new HttpGet("/");
    try (final CloseableHttpResponse response = customClient.execute(target, httpGet)) {
        EntityUtils.consume(response.getEntity());
    }
}
